    src = os.path.join(os.path.dirname(__file__), "..", "src")
    proc = subprocess.run(
        [sys.executable, os.path.join(src, "wordfreq.py"), "2"],
        input="one two two three three three",
        capture_output=True,
        text=True,
        check=True,
    )
    assert proc.stdout.splitlines() == ["three 3", "two 2"]

