    def test_known_sample(self):
        self.assertEqual(
            summarize("a b a"),
            {"words": 3, "chars": 5, "unique_words": 2},
        )

    def test_empty(self):
        self.assertEqual(
            summarize(""),
            {"words": 0, "chars": 0, "unique_words": 0},
        )


if __name__ == "__main__":
    unittest.main()

